def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    strong_prev_bids = []
    weak_count = 0
    desperate_count = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > DAILY_SALARY * 2:
                strong_prev_bids.append(float(bid))
        if opp.get('budget', 0) < DAILY_SALARY * 0.75 or opp.get('hp', 10) <= 2:
            weak_count += 1
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strong_highest_prev = max(strong_prev_bids) if strong_prev_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.55
    elif hp <= 4:
        danger += 0.3
    if no_water >= 2:
        danger += 0.35
    elif no_water >= 1:
        danger += 0.18
    danger += scarcity * 0.28
    if desperate_count >= 2:
        danger += 0.08

    if day >= 8:
        danger += 0.08

    if hp <= 2 or no_water >= 2:
        base = DAILY_SALARY * (0.92 + 0.35 * scarcity)
        target = max(base, strong_highest_prev + 6.0)
    elif scarcity >= 0.7:
        base = DAILY_SALARY * (0.58 + 0.22 * danger)
        target = max(base, strong_highest_prev + 2.5)
    elif scarcity <= 0.25 and hp >= 6 and no_water == 0:
        target = DAILY_SALARY * 0.22
        if strong_highest_prev < DAILY_SALARY * 0.45:
            target = max(target, strong_highest_prev + 1.2)
    else:
        base = DAILY_SALARY * (0.34 + 0.34 * danger)
        target = max(base, min(strong_highest_prev + 1.8, DAILY_SALARY * 0.88))

    if weak_count >= 2 and hp >= 5 and no_water == 0:
        target *= 0.92

    if highest_prev >= 180 and hp >= 5 and no_water == 0:
        target = min(target, DAILY_SALARY * 0.42)

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 1.2
    elif day <= 9:
        reserve = DAILY_SALARY * 0.5

    spend_cap = budget - reserve
    if spend_cap < 0:
        spend_cap = budget * 0.55
    if hp <= 2 or no_water >= 2:
        spend_cap = budget

    bid = min(target, spend_cap, budget)
    if bid < 0:
        bid = 0.0

    if bid > 0 and bid < 1.0:
        bid = min(1.0, budget)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_amount = DAILY_SALARY * 1.0

    if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
        bid_amount = DAILY_SALARY * 1.9
    elif my_status['hp'] <= 5:
        bid_amount = DAILY_SALARY * 1.3

    if day_context['supply'] <= WATER_REQ + 4:
        bid_amount *= 1.1
    elif day_context['supply'] >= WATER_REQ * 1.8:
        bid_amount *= 0.9

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 1.5:
            bid_amount = max(bid_amount, highest_prev_bid * 1.05)
        elif highest_prev_bid > bid_amount * 0.9:
            bid_amount = max(bid_amount, highest_prev_bid + 5)

    final_bid = min(my_status['budget'], bid_amount)
    final_bid = max(0.0, final_bid)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days == 0:
        if my_status['hp'] >= WATER_REQ:
            final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)
        else:
            final_bid = my_status['budget']

    return final_bid
